package gr.dit.hua.Foodie.core.model;

import jakarta.persistence.*;
import org.hibernate.annotations.CreationTimestamp;

import java.time.Instant;

// A registered user of the system. Customers and owners are both stored here,
// and the role field tells them apart. Visitors are not stored (they are just not logged in).
@Entity
@Table(name = "foodie_user")
public class User {

    // Primary key, generated by the database
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id")
    private Long id;

    // Unique, so no two users share a username
    @Column(name = "username", nullable = false, unique = true, length = 255)
    private String username;

    // Unique, so it can also identify the user at login
    @Column(name = "email", nullable = false, unique = true, length = 255)
    private String email;

    @Column(name = "mobile_phone_number", nullable = false, length = 18)
    private String mobilePhoneNumber;  //E164


    // BCrypt hash of the password. The plain password is never stored.
    @Column(name = "password_hash", nullable = false, length = 255)
    private String passwordHash;

    // Stored as text (CUSTOMER / OWNER) instead of a number, so the data
    // stays correct if the enum order changes later
    @Enumerated(EnumType.STRING)
    @Column(name = "role", nullable = false, length = 20)
    private Role role;

    @CreationTimestamp
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    // Required by JPA, not for our own use
    protected User() {
    }

    public User(Long id, String username, String email, String mobilePhoneNumber, String passwordHash, Role role, Instant createdAt) {
        this.id = id;
        this.username = username;
        this.email = email;
        this.mobilePhoneNumber = mobilePhoneNumber;
        this.passwordHash = passwordHash;
        this.role = role;
        this.createdAt = createdAt;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getMobilePhoneNumber() {
        return mobilePhoneNumber;
    }

    public void setMobilePhoneNumber(String mobilePhoneNumber) {
        this.mobilePhoneNumber = mobilePhoneNumber;
    }

    public String getPasswordHash() {
        return passwordHash;
    }

    public void setPasswordHash(String passwordHash) {
        this.passwordHash = passwordHash;
    }

    public Role getRole() {
        return role;
    }

    public void setRole(Role role) {
        this.role = role;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }

    @Override
    public String toString() {
        return "User{" +
                "id=" + id +
                ", username='" + username + '\'' +
                ", role=" + role +
                '}';
    }
}